package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
)

const tasksFile = "tasks.json"

// Task represents a single todo item
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Global variable to hold tasks in memory
var tasks []Task

func init() {
	// Load tasks from file when the program starts
	if err := loadTasks(); err != nil {
		// If the file doesn't exist or is empty, initialize an empty task list
		tasks = []Task{}
	}
}

func loadTasks() error {
	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		return err // File might not exist yet, or other read error
	}
	if len(data) == 0 {
		return fmt.Errorf("tasks file is empty")
	}
	return json.Unmarshal(data, &tasks)
}

func saveTasks() error {
	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return err
	}
	return ioutil.WriteFile(tasksFile, data, 0644)
}

func printErrorAndExit(err string, code int) {
	output := map[string]string{"error": err}
	jsonOutput, _ := json.Marshal(output)
	fmt.Println(string(jsonOutput))
	os.Exit(code)
}

func getNextID() int {
	if len(tasks) == 0 {
		return 1
	}
	maxID := 0
	for _, task := range tasks {
		if task.ID > maxID {
			maxID = task.ID
		}
	}
	return maxID + 1
}

func main() {
	// Subcommands
	addCmd := flag.NewFlagSet("add", flag.ExitOnError)
	addDescription := addCmd.String("description", "", "Description of the task")

	listCmd := flag.NewFlagSet("list", flag.ExitOnError)

	doneCmd := flag.NewFlagSet("done", flag.ExitOnError)
	doneID := doneCmd.Int("id", 0, "ID of the task to complete")

	if len(os.Args) < 2 {
		printErrorAndExit("no command provided", 42)
	}

	switch os.Args[1] {
	case "add":
		addCmd.Parse(os.Args[2:])
		if *addDescription == "" {
			printErrorAndExit("invalid arguments: description is required", 42)
		}
		task := Task{
			ID:          getNextID(),
			Description: *addDescription,
			Done:        false,
		}
		tasks = append(tasks, task)
		if err := saveTasks(); err != nil {
			printErrorAndExit(fmt.Sprintf("failed to save tasks: %v", err), 1)
		}
		output := map[string]interface{}{"id": task.ID, "status": "added"}
		jsonOutput, _ := json.Marshal(output)
		fmt.Println(string(jsonOutput))

	case "list":
		listCmd.Parse(os.Args[2:])
		var pendingTasks []Task
		for _, task := range tasks {
			if !task.Done {
				pendingTasks = append(pendingTasks, task)
			}
		}
		jsonOutput, err := json.Marshal(pendingTasks)
		if err != nil {
			printErrorAndExit(fmt.Sprintf("failed to marshal tasks: %v", err), 1)
		}
		fmt.Println(string(jsonOutput))

	case "done":
		doneCmd.Parse(os.Args[2:])
		if *doneID == 0 {
			printErrorAndExit("invalid arguments: task ID is required", 42)
		}
		found := false
		for i := range tasks {
			if tasks[i].ID == *doneID {
				tasks[i].Done = true
				found = true
				break
			}
		}
		if !found {
			printErrorAndExit(fmt.Sprintf("task with ID %d not found", *doneID), 1)
		}
		if err := saveTasks(); err != nil {
			printErrorAndExit(fmt.Sprintf("failed to save tasks: %v", err), 1)
		}
		output := map[string]interface{}{"id": *doneID, "status": "completed"}
		jsonOutput, _ := json.Marshal(output)
		fmt.Println(string(jsonOutput))

	default:
		printErrorAndExit(fmt.Sprintf("unknown command: %s", os.Args[1]), 42)
	}
}

