	}

	if len(savedTasks) != 1 || savedTasks[0].Description != "Buy groceries" || savedTasks[0].ID != 1 || savedTasks[0].Done != false {
		t.Errorf("Saved tasks mismatch: %v", savedTasks)
	}
}

